package local.m13.home;

import android.app.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import java.util.*;

/** Minimal full-screen player. The existing service keeps owning the audio. */
public final class MusicPlayerActivity extends Activity {
    private final Handler ui=new Handler();private TextView title,artist,previous,line,next,time,play;
    private SeekBar seek;private boolean dragging;private int ticks,offset;private String track="";private MusicStore store;
    private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);return t;}
    private void set(TextView t,String value){if(!android.text.TextUtils.equals(t.getText(),value))t.setText(value);}
    private void button(LinearLayout row,final TextView b,final Runnable action){b.setPadding(dp(18),0,dp(18),0);b.setFocusable(true);b.setClickable(true);GradientDrawable bg=new GradientDrawable();bg.setColor(0xff24446b);bg.setCornerRadius(dp(12));b.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.setMargins(dp(6),0,dp(6),0);row.addView(b,p);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});b.setOnFocusChangeListener(new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean focused){GradientDrawable d=focused?BlueRedTheme.focus(dp(12)):new GradientDrawable();if(focused)d.setStroke(dp(2),BlueRedTheme.TEXT);else{d.setColor(0xff24446b);d.setCornerRadius(dp(12));}b.setBackground(d);b.setTextColor(focused?BlueRedTheme.DARK:BlueRedTheme.TEXT);}});}
    public void onCreate(Bundle state){super.onCreate(state);store=new MusicStore(this);getWindow().setFlags(1024,1024);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(dp(52),dp(24),dp(52),dp(28));root.setBackground(BlueRedTheme.background(0));
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView brand=new BlueRedTheme.BrandText(this);brand.setText("轻音乐");brand.setTextSize(23);header.addView(brand,new LinearLayout.LayoutParams(0,dp(48),1));button(header,text("歌词字号",14,BlueRedTheme.TEXT),new Runnable(){public void run(){MusicUi.chooseSize(MusicPlayerActivity.this,new Runnable(){public void run(){font();}});}});button(header,text("播放设置",14,BlueRedTheme.TEXT),new Runnable(){public void run(){MusicUi.options(MusicPlayerActivity.this);}});final TextView back=text("返回列表",14,BlueRedTheme.TEXT);button(header,back,new Runnable(){public void run(){finish();}});root.addView(header,new LinearLayout.LayoutParams(-1,dp(54)));
        title=text("此刻，只听音乐",28,BlueRedTheme.TEXT);title.setMaxLines(2);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(title,new LinearLayout.LayoutParams(-1,dp(76)));artist=text("",15,BlueRedTheme.MUTED);artist.setSingleLine(true);artist.setEllipsize(android.text.TextUtils.TruncateAt.END);root.addView(artist,new LinearLayout.LayoutParams(-1,dp(32)));
        LinearLayout lyrics=new LinearLayout(this);lyrics.setOrientation(1);lyrics.setGravity(Gravity.CENTER);previous=text("",18,BlueRedTheme.FAINT);previous.setMaxLines(2);lyrics.addView(previous,new LinearLayout.LayoutParams(-1,dp(62)));line=text("",34,BlueRedTheme.BLUE);line.setMaxLines(3);lyrics.addView(line,new LinearLayout.LayoutParams(-1,0,1));next=text("",18,BlueRedTheme.FAINT);next.setMaxLines(2);lyrics.addView(next,new LinearLayout.LayoutParams(-1,dp(62)));root.addView(lyrics,new LinearLayout.LayoutParams(-1,0,1));
        seek=new SeekBar(this);seek.setMax(1000);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){MusicService m=MusicService.current();if(user&&!dragging&&m!=null)m.seek((int)((long)m.duration()*value/1000));}public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onStopTrackingTouch(SeekBar s){MusicService m=MusicService.current();if(m!=null)m.seek((int)((long)m.duration()*s.getProgress()/1000));dragging=false;}});root.addView(seek,new LinearLayout.LayoutParams(-1,dp(34)));time=text("00:00 / 00:00",13,BlueRedTheme.MUTED);root.addView(time,new LinearLayout.LayoutParams(-1,dp(28)));
        LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);button(controls,text("上一首",15,BlueRedTheme.TEXT),new Runnable(){public void run(){MusicService.command(MusicPlayerActivity.this,"previous");}});play=text("播放",15,BlueRedTheme.TEXT);button(controls,play,new Runnable(){public void run(){MusicService.command(MusicPlayerActivity.this,"toggle");}});button(controls,text("下一首",15,BlueRedTheme.TEXT),new Runnable(){public void run(){MusicService.command(MusicPlayerActivity.this,"next");}});root.addView(controls,new LinearLayout.LayoutParams(-1,dp(52)));setContentView(root);TvUi.inset(this);play.requestFocus();font();}
    private void font(){int size=MusicUi.lyricSize(this,true);if(Math.abs(line.getTextSize()-size*getResources().getDisplayMetrics().scaledDensity)>.1f)line.setTextSize(size);}
    protected void onResume(){super.onResume();TvUi.inset(this);ScreenPolicy.awaken(this);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);font();ui.removeCallbacks(tick);ui.post(tick);}
    protected void onPause(){ui.removeCallbacks(tick);super.onPause();}
    protected void onDestroy(){ui.removeCallbacksAndMessages(null);super.onDestroy();}
    private final Runnable tick=new Runnable(){public void run(){render();ui.postDelayed(this,100);}};
    private String clock(int ms){int s=Math.max(0,ms)/1000;return String.format(Locale.US,"%02d:%02d",s/60,s%60);}
    private void render(){font();MusicService m=MusicService.current();if(m==null||m.song().optString("id").isEmpty()){set(line,"请返回列表选择歌曲");return;}int position=m.position();String key=MusicStore.key(m.song());if(!key.equals(track)){track=key;offset=store.lyricDelay(m.song());ticks=0;}
        if(ticks++%5==0){set(title,m.song().optString("name"));set(artist,m.song().optString("artist"));set(time,clock(position)+" / "+clock(m.duration()));set(play,"playing".equals(m.state())?"暂停":"播放");if(!dragging)seek.setProgress(m.duration()>0?(int)((long)position*1000/m.duration()):0);}
        List<MusicLyrics.Line> lines=m.lyrics();int current=MusicLyrics.current(lines,position,offset);if("error".equals(m.state())){set(line,m.error());set(previous,"");set(next,"");}else if("loading".equals(m.state())){set(line,"正在连接音乐源…");set(previous,"");set(next,"");}else if(lines.isEmpty()){set(line,"随音乐，慢下来");set(previous,"");set(next,"当前来源暂无同步歌词");}else{set(previous,current>0?lines.get(current-1).text:"");set(line,current>=0?lines.get(current).text:"前奏 · 即将开始");set(next,current+1<lines.size()?lines.get(current+1).text:"");}}
    public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){MusicService.command(this,"toggle");return true;}if(key==KeyEvent.KEYCODE_MEDIA_NEXT){MusicService.command(this,"next");return true;}if(key==KeyEvent.KEYCODE_MEDIA_PREVIOUS){MusicService.command(this,"previous");return true;}return super.onKeyDown(key,event);}
}
